data_contract.table:
id; work_order_id FK work_orders cascadeOnDelete (index); product_id FK products
restrictOnDelete; quote_line_id nullable FK quote_lines nullOnDelete (index);
quantity decimal(15,2); unit_of_measure_id nullable FK nullOnDelete (congelata come in
quote_lines); unit_price decimal(15,2); vat_rate_id nullable FK nullOnDelete;
net_amount, vat_amount, total_amount decimal(15,2); incurred_on date;
supplier_id nullable FK registries nullOnDelete (index); document_reference
string(100) nullable; additional_description text nullable; sort_order unsigned int;
timestamps.

data_contract.shape:
{ lines: WorkOrderCostLine[],
  budget: {
    allocated_lines: QuoteLineResource[]     (COST con offer_line_id in righe commessa),
    unallocated_lines: QuoteLineResource[]   (COST con offer_line_id null, informativo)
  },
  comparison: {
    rows: [{ quote_line_id: int, product: {id, code, name}, revenue_net,
             budget_cost_net, actual_cost_net, delta_net }]   (una per riga ricavo
             della commessa, ordinate come WorkOrder::quoteLines),
    unattributed_actual_cost_net,             (costi reali con quote_line_id null)
    totals: { revenue_net, budget_cost_net, actual_cost_net, delta_net,
              budget_margin_net, actual_margin_net }
  } }
Tutti gli importi del confronto: "decimal string" a 2 decimali.
totals.actual_cost_net include unattributed_actual_cost_net; totals.budget_cost_net
esclude unallocated_lines (D-1). delta = actual − budget; margin = revenue − cost.
